create table if not exists public.questionnaires (id text primary key, clinic_id text not null references public.clinics(id) on delete restrict, patient_id text not null references public.patients(id) on delete restrict, assigned_by_profile_id text not null references public.profiles(id), questionnaire_type text not null check (questionnaire_type in ('ASRS','AQ10','AQ50','CAT_Q','PHQ9','GAD7','WSAS','SNAP_IV','CONNERS','SDQ','WURS','INFORMANT_REPORT')), title text not null, status text not null default 'ASSIGNED' check (status in ('ASSIGNED','IN_PROGRESS','SUBMITTED','REVIEWED','EXPIRED')), due_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists questionnaires_patient_status_idx on public.questionnaires(patient_id,status,created_at desc);
alter table public.questionnaires enable row level security;
create policy questionnaires_clinic_isolation on public.questionnaires for all using (public.has_clinic_membership(clinic_id)) with check (public.has_clinic_membership(clinic_id));
create table if not exists public.informant_questionnaire_links (id text primary key, clinic_id text not null references public.clinics(id) on delete restrict, patient_id text not null references public.patients(id) on delete restrict, questionnaire_id text not null references public.questionnaires(id) on delete cascade, email text not null, relationship text not null, token_digest text not null unique, expires_at timestamptz not null, used_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now());
create index if not exists informant_links_questionnaire_idx on public.informant_questionnaire_links(questionnaire_id,expires_at);
alter table public.informant_questionnaire_links enable row level security;
create policy informant_links_clinic_isolation on public.informant_questionnaire_links for all using (public.has_clinic_membership(clinic_id)) with check (public.has_clinic_membership(clinic_id));
create table if not exists public.questionnaire_submissions (id text primary key, clinic_id text not null references public.clinics(id) on delete restrict, questionnaire_id text not null references public.questionnaires(id) on delete restrict, submitted_by_profile_id text references public.profiles(id) on delete set null, answers jsonb not null, submitted_at timestamptz not null default now(), reviewed_at timestamptz, reviewed_by_profile_id text references public.profiles(id) on delete set null);
alter table public.questionnaire_submissions enable row level security;
create policy questionnaire_submissions_clinic_isolation on public.questionnaire_submissions for all using (public.has_clinic_membership(clinic_id)) with check (public.has_clinic_membership(clinic_id));
